from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    result: List[str] = []
    current: List[str] = []
    current_depth = 0

    for c in paren_string:
        if c.isspace():
            continue
        if c == '(':
            current_depth += 1
            current.append(c)
        elif c == ')':
            current_depth -= 1
            current.append(c)
            if current_depth == 0:
                result.append(''.join(current))
                current.clear()
        else:
            # ignore any non‑parenthesis, non‑space characters
            continue

    return result
